// ═══════════════════════════════════════════════════════════════
//  SNAPSHOT WRITER  v1.2
//  + Rate limiter: max 1 írás / 5 perc
//
//  Node-RED beállítás:
//    - Outputs: 5
//    - Output 1 → mysql node (snap_weather)
//    - Output 2 → mysql node (snap_sensors_th)
//    - Output 3 → mysql node (snap_ac)
//    - Output 4 → mysql node (snap_heating)
//    - Output 5 → mysql node (snap_shutters)
// ═══════════════════════════════════════════════════════════════

// ── RATE LIMITER: max 1 írás / 5 perc ────────────────────────
const INTERVAL_MS = 5 * 60 * 1000;
const lastWrite = context.get('lastWrite') || 0;
const now = Date.now();

if (now - lastWrite < INTERVAL_MS) return null;
context.set('lastWrite', now);

// ─────────────────────────────────────────────────────────────

const p = msg.payload;
if (!p) return null;

const tsMs  = p._ts || now;
const tsStr = new Date(tsMs).toISOString().slice(0, 19).replace('T', ' ');

function esc(v) {
    if (v === null || v === undefined) return 'NULL';
    if (typeof v === 'boolean') return v ? 1 : 0;
    if (typeof v === 'number' && Number.isFinite(v)) return v;
    return `'${String(v).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

// ── OUTPUT 1: snap_weather ────────────────────────────────────
let msgWeather = null;
const w = p.weather;
if (w) {
    const sr = w.sunrise ? String(w.sunrise).slice(0, 5) : null;
    const ss = w.sunset  ? String(w.sunset).slice(0, 5)  : null;
    msgWeather = {
        topic: `INSERT INTO snap_weather
(ts, temp, humidity, wind, gust, wx_code, temp_min, temp_max, sunrise, sunset)
VALUES (
    '${tsStr}',
    ${esc(w.temp     ?? null)},
    ${esc(w.humidity ?? null)},
    ${esc(w.wind     ?? null)},
    ${esc(w.gust     ?? null)},
    ${esc(w.code     ?? null)},
    ${esc(w.tempMin  ?? null)},
    ${esc(w.tempMax  ?? null)},
    ${sr ? `'${sr}'` : 'NULL'},
    ${ss ? `'${ss}'` : 'NULL'}
);`
    };
}

// ── OUTPUT 2: snap_sensors_th ─────────────────────────────────
let msgSensors = null;
const th = p.sensors?.th || {};
const thRooms = Object.keys(th);
if (thRooms.length > 0) {
    const values = thRooms.map(room => {
        const s = th[room] || {};
        return `('${tsStr}', ${esc(room)}, ${esc(s.temp ?? null)}, ${esc(s.hum ?? null)}, ${esc(s.battery ?? null)}, ${s.online !== false ? 1 : 0})`;
    });
    msgSensors = {
        topic: `INSERT INTO snap_sensors_th
(ts, room, temp, humidity, battery, online)
VALUES ${values.join(',\n')};`
    };
}

// ── OUTPUT 3: snap_ac ─────────────────────────────────────────
let msgAc = null;
const ac = p.ac;
if (ac) {
    msgAc = {
        topic: `INSERT INTO snap_ac
(ts, power, room_temp, set_temp, mode_code, offline)
VALUES (
    '${tsStr}',
    ${ac.power   ? 1 : 0},
    ${esc(ac.roomTemp ?? null)},
    ${esc(ac.setTemp  ?? null)},
    ${esc(ac.modeCode ?? ac.mode ?? null)},
    ${ac.offline ? 1 : 0}
);`
    };
}

// ── OUTPUT 4: snap_heating ────────────────────────────────────
let msgHeating = null;
const ft = p.sensors?.switches?.futes || {};
const heatingValues = Object.entries(ft).map(([name, val]) => {
    const state = val === true ? 1 : 0;
    return `('${tsStr}', ${esc(name)}, ${state})`;
});
if (heatingValues.length > 0) {
    msgHeating = {
        topic: `INSERT INTO snap_heating
(ts, relay_name, state)
VALUES ${heatingValues.join(',\n')};`
    };
}

// ── OUTPUT 5: snap_shutters ───────────────────────────────────
let msgShutters = null;
const shutters = p.sensors?.shutters || {};
const shutterValues = [];
for (const room of Object.keys(shutters)) {
    const labels = shutters[room];
    for (const label of Object.keys(labels)) {
        const s = labels[label];
        shutterValues.push(
            `('${tsStr}', ${esc(room)}, ${esc(label)}, ${esc(s.pct ?? null)}, ${esc(s.motor ?? null)})`
        );
    }
}
if (shutterValues.length > 0) {
    msgShutters = {
        topic: `INSERT INTO snap_shutters
(ts, room, label, position_pct, motor)
VALUES ${shutterValues.join(',\n')};`
    };
}

return [msgWeather, msgSensors, msgAc, msgHeating, msgShutters];

let d = msg.payload || {};
let daily = d.daily || {};
let hourly = d.hourly || {};

let minT = daily.temperature_2m_min ? daily.temperature_2m_min[0] : null;
let maxT = daily.temperature_2m_max ? daily.temperature_2m_max[0] : null;

if (minT == null && hourly.temperature_2m) {
  minT = Math.min(...hourly.temperature_2m);
  maxT = Math.max(...hourly.temperature_2m);
}

let trend = '-';
if (hourly.temperature_2m?.length > 5) {
  let s = hourly.temperature_2m[0];
  let e = hourly.temperature_2m[hourly.temperature_2m.length - 1];
  trend = e > s ? '🌞 Felmelegedés várható' : '❄️ Lehűlés várható';
}

let avgWind = hourly.wind_speed_10m?.length
  ? (hourly.wind_speed_10m.reduce((a, b) => a + b, 0) / hourly.wind_speed_10m.length).toFixed(1)
  : '-';

let sunrise = daily.sunrise ? daily.sunrise[0] : '-';
let sunset  = daily.sunset  ? daily.sunset[0]  : '-';

const f1 = (x) => (x == null || Number.isNaN(Number(x))) ? '-' : Number(x).toFixed(1);

// --- CSAPADÉK (daily preferált) ---
const precipSum = (daily.precipitation_sum && daily.precipitation_sum.length)
  ? Number(daily.precipitation_sum[0])
  : (hourly.precipitation?.length ? hourly.precipitation.reduce((a,b)=>a+b,0) : null);

const precipProbMax = (daily.precipitation_probability_max && daily.precipitation_probability_max.length)
  ? Number(daily.precipitation_probability_max[0])
  : (hourly.precipitation_probability?.length ? Math.max(...hourly.precipitation_probability) : null);

// formázott csapadék szöveg (amit közvetlenül ki tudsz írni)
let precipText = '-';
const parts = [];
if (Number.isFinite(precipSum)) parts.push(`${precipSum.toFixed(1)} mm`);
if (Number.isFinite(precipProbMax)) parts.push(`${precipProbMax.toFixed(0)}% esély`);
if (parts.length) precipText = parts.join(' • ');

msg.payload = {
  minTemp: f1(minT),
  maxTemp: f1(maxT),
  trend,
  avgWind,
  sunrise,
  sunset,

  // új mezők:
  precipSum: Number.isFinite(precipSum) ? precipSum : null,
  precipProbMax: Number.isFinite(precipProbMax) ? precipProbMax : null,
  precipText
};



msg.topic = 'forecast';
return msg;

let r = msg.payload?.rates?.HUF;
const TZ='Europe/Budapest';
const date = new Intl.DateTimeFormat('en-CA', { timeZone: TZ }).format(new Date()); // YYYY-MM-DD
msg.payload = r ? { rate: Number(r).toFixed(2), date } : { rate:"-", date:"-" };
msg.topic = "fx";
return msg;

const TZ = 'Europe/Budapest';

// ---- Beállítások ----
const SAMPLE_MIN = 5;                         // nálad 5 perc a mintavételezés
const SAMPLE_MS  = SAMPLE_MIN * 60 * 1000;
const MAX_GAP_MS = 2 * SAMPLE_MS;             // ha ennél nagyobb a rés, akkor ne számoljuk bele teljesen

const RELAY_ON_VALUE  = 1;                    // relay_state: 1 = ON
const BOILER_ON_VALUE = 1;                    // boiler_state: 1 = ON

const now = new Date();
const isoDate = new Intl.DateTimeFormat('en-CA', { timeZone: TZ }).format(now); // YYYY-MM-DD
const huDateLong = new Intl.DateTimeFormat('hu-HU', {
  timeZone: TZ, weekday: 'long', year: 'numeric', month: 'long', day: '2-digit'
}).format(now);

// ---- Inputok ----
const sql     = msg.payload.sql || [];
const f       = msg.payload.forecast || {};
const fx      = msg.payload.fx || {};
const lunch   = msg.payload.lunch || {};
const nameday = msg.payload.nameday || {};
const kuka = msg.payload.kuka || msg.payload.kukaReminder || '';


// ---- Helpers ----
const toMs = (ts) => {
  if (ts == null) return null;

  // number: epoch sec vagy ms
  if (typeof ts === 'number' && Number.isFinite(ts)) {
    return ts < 1e12 ? ts * 1000 : ts;
  }

  const s = String(ts).trim();

  // numeric string: epoch sec vagy ms
  if (/^\d+$/.test(s)) {
    const n = Number(s);
    if (!Number.isFinite(n)) return null;
    return n < 1e12 ? n * 1000 : n;
  }

  const t = Date.parse(s);
  return Number.isFinite(t) ? t : null;
};

const ICON = {
  sun: '☀️',
  weather: '🌦',
  rain: '☔',
  wind: '🌬️',     // 💨 helyett ez “szelesebb”
  sunrise: '🌅',
  sunset: '🌇',
  lunch: '🍽️',
  eur: '💶',
  tip: '💡'
};

const fnum = (n, d = 1) =>
  (n == null || Number.isNaN(Number(n))) ? '-' : Number(n).toFixed(d);

const avg = (a) => a.length ? (a.reduce((x, y) => x + y, 0) / a.length) : null;
const min = (a) => a.length ? Math.min(...a) : null;
const max = (a) => a.length ? Math.max(...a) : null;

const fmtHHMM = (ms) => {
  if (!ms || ms <= 0) return '00:00';
  const totalMin = Math.floor(ms / 60000);
  const hh = String(Math.floor(totalMin / 60)).padStart(2, '0');
  const mm = String(totalMin % 60).padStart(2, '0');
  return `${hh}:${mm}`;
};

const timeHHMM = (s) => {
  if (!s) return '-';
  // open-meteo: "YYYY-MM-DDTHH:MM"
  const m = String(s).match(/T(\d{2}:\d{2})/);
  if (m) return m[1];
  try {
    return new Date(s).toLocaleTimeString('hu-HU', {
      timeZone: TZ, hour: '2-digit', minute: '2-digit'
    });
  } catch {
    return '-';
  }
};

// ---- ON-idő számolás (rés-kezeléssel) ----
function calcOnMsClamped(points, key, onValue) {
  // points: [{timestamp, relay_state/boiler_state}]
  if (!Array.isArray(points) || points.length < 2) return 0;

  // dedup timestamp szerint (ha lenne duplikáció)
  const m = new Map(); // ms -> state
  for (const p of points) {
    const ms = toMs(p.timestamp);
    if (ms == null) continue;
    // ha több jön ugyanarra a ms-re, az utolsót vegyük
    m.set(ms, Number(p[key]));
  }

  const arr = Array.from(m.entries())
    .sort((a, b) => a[0] - b[0])
    .map(([ms, state]) => ({ ms, state }));

  if (arr.length < 2) return 0;

  let onMs = 0;
  for (let i = 0; i < arr.length - 1; i++) {
    const t0 = arr[i].ms;
    const t1 = arr[i + 1].ms;
    const rawDt = Math.max(0, t1 - t0);

    // ha túl nagy a kimaradás, ne számoljuk bele az egész rést (különben elszáll 9+ órára)
    const dt = rawDt > MAX_GAP_MS ? SAMPLE_MS : rawDt;

    const isOn = (Number(arr[i].state) === onValue);
    if (isOn) onMs += dt;
  }

  return onMs;
}

// ---- Kültéri / kazán sorozat dedup timestamp szerint ----
// Mivel minden szobához van rekord ugyanazzal a timestamp-pel, itt timestamp alapján dedupolunk.
const byTs = new Map(); // ms -> { outdoor_temp, outdoor_hum, boiler_state }
for (const r of sql) {
  const ms = toMs(r.timestamp);
  if (ms == null) continue;
  if (!byTs.has(ms)) {
    byTs.set(ms, {
      timestamp: r.timestamp,
      outdoor_temp: r.outdoor_temp,
      outdoor_hum: r.outdoor_hum,
      boiler_state: r.boiler_state
    });
  }
}
const uniqTs = Array.from(byTs.values());

const outTemps = uniqTs.filter(x => x.outdoor_temp != null).map(x => Number(x.outdoor_temp));
const outHums  = uniqTs.filter(x => x.outdoor_hum  != null).map(x => Number(x.outdoor_hum));

const outAvgT = fnum(avg(outTemps), 1);
const outAvgH = fnum(avg(outHums), 0);

const boilerOnMs   = calcOnMsClamped(uniqTs, 'boiler_state', BOILER_ON_VALUE);
const boilerOnHHMM = fmtHHMM(boilerOnMs);

// ---- Szobánként aggregálás + ON idő ----
const rooms = {}; // room -> { t:[], h:[], series:[{timestamp, relay_state}] }

for (const r of sql) {
  const room = (r.room_name || r.relay_name || 'Ismeretlen').toString();
  if (!rooms[room]) rooms[room] = { t: [], h: [], series: [] };

  if (r.indoor_temp != null) rooms[room].t.push(Number(r.indoor_temp));
  if (r.indoor_hum  != null) rooms[room].h.push(Number(r.indoor_hum));

  rooms[room].series.push({ timestamp: r.timestamp, relay_state: r.relay_state });
}

let rows = '';
const roomNames = Object.keys(rooms).sort((a, b) => a.localeCompare(b, 'hu'));
for (const room of roomNames) {
  const s = rooms[room];
  const onMs = calcOnMsClamped(s.series, 'relay_state', RELAY_ON_VALUE);

  rows += `<tr>
  <td style="text-align:left;padding:8px 10px;border:1px solid #e5e7eb;font-size:13px;font-weight:600;white-space:nowrap;">${room}</td>
  <td style="text-align:right;padding:8px 10px;border:1px solid #e5e7eb;font-size:13px;font-variant-numeric:tabular-nums;">${fnum(avg(s.t), 1)} °C</td>
  <td style="text-align:right;padding:8px 10px;border:1px solid #e5e7eb;font-size:13px;font-variant-numeric:tabular-nums;">${fnum(min(s.t), 1)} °C</td>
  <td style="text-align:right;padding:8px 10px;border:1px solid #e5e7eb;font-size:13px;font-variant-numeric:tabular-nums;">${fnum(max(s.t), 1)} °C</td>
  <td style="text-align:right;padding:8px 10px;border:1px solid #e5e7eb;font-size:13px;font-variant-numeric:tabular-nums;">${fnum(avg(s.h), 0)} %</td>
  <td style="text-align:right;padding:8px 10px;border:1px solid #e5e7eb;font-size:13px;font-variant-numeric:tabular-nums;color:#0f766e;"><b>${fmtHHMM(onMs)}</b></td>
</tr>`;
}
// ---- Kuka emlékeztető (Sheets cellából) ----
const toTextCell = (v) => {
  if (v == null) return '';
  // ha google sheet node 2D tömböt ad: [[...]]
  if (Array.isArray(v)) {
    if (Array.isArray(v[0])) return String(v[0][0] ?? '').trim();
    return String(v[0] ?? '').trim();
  }
  return String(v).trim();
};

const kukaText = toTextCell(kuka);

const GLASS_AMBER = [
  "margin-top:12px",
  "padding:10px 12px",
  "border-radius:14px",
  "border:1px solid rgba(251,191,36,0.55)",
  "background:rgba(255,251,235,0.78)",
  "box-shadow:0 10px 26px rgba(17,24,39,0.10), inset 0 1px 0 rgba(255,255,255,0.60)",
  "backdrop-filter:blur(10px)",
  "-webkit-backdrop-filter:blur(10px)",
].join(";");

const kukaBlock = kukaText
  ? `<div style="${GLASS_AMBER}">
       🔔 <b>Huladékszállítás emlékeztető</b><br>
       ${kukaText}
     </div>`
  : ``;



// ---- Névnap / ebéd ----
const namedayMain = (nameday.main && String(nameday.main).trim()) ? String(nameday.main).trim() : '-';
const namedayOther = (nameday.other && String(nameday.other).trim()) ? String(nameday.other).trim() : '';
const namedayOtherShort = namedayOther.length > 140 ? (namedayOther.slice(0, 140) + '…') : namedayOther;

const lunchText = (lunch.lunch && String(lunch.lunch).trim()) ? String(lunch.lunch).trim() : '-';

// ---- Forecast ----
const sunrise = timeHHMM(f.sunrise);
const sunset  = timeHHMM(f.sunset);

// ---- Barátságos napi tipp (időjárás alapján) ----

const pSum = Number(f.precipSum);
const pProb = Number(f.precipProbMax);
const minT = Number(f.minTemp);
const maxT = Number(f.maxTemp);
const avgWind = Number(f.avgWind);
const trendTxt = (f.trend || '').toString().toLowerCase();

let tip = '';
if ((Number.isFinite(pProb) && pProb >= 60) || (Number.isFinite(pSum) && pSum >= 2)) {
  tip = 'Csapadék esélyes nap — egy esernyő/kabát nem rossz ötlet, és az utak is csúszósabbak lehetnek.';
} else if  (Number.isFinite(minT) && minT <= 0) {
  tip = 'Reggel fagyhat — érdemes rétegesen öltözni, és a csúszós részekre figyelni.';
} else if (trendTxt.includes('lehű') || trendTxt.includes('hűv')) {
  tip = 'Lehűlés várható — egy plusz réteg jól jöhet, főleg reggel és este.';
} else if (trendTxt.includes('meleg') || trendTxt.includes('enyh')) {
  tip = 'Enyhébb idő jöhet — ha teheted, szellőztess egyet napközben.';
} else if (Number.isFinite(avgWind) && avgWind >= 25) {
  tip = 'Szeles napnak nézünk elébe — a szélérzet jóval hűvösebb lehet.';
} else if (Number.isFinite(maxT) && maxT >= 25) {
  tip = 'Melegebb nap lesz — hidratálás, és egy kis árnyék aranyat ér.';
} else {
  tip = 'Legyen nyugodt, gördülékeny napod — ha bármi szokatlan, lentebb rögtön látni fogod. 🙂';
}
// ---- Liquid-glass box style (email-safe) ----
const GLASS_CARD = [
  "border:1px solid rgba(255,255,255,0.55)",
  "background:rgba(255,255,255,0.72)",
  "border-radius:16px",
  "box-shadow:0 10px 26px rgba(17,24,39,0.10)",
  "backdrop-filter:blur(10px)",
  "-webkit-backdrop-filter:blur(10px)",
].join(";");

const GLASS_INNER = [
  "border:1px solid rgba(255,255,255,0.45)",
  "background:rgba(255,255,255,0.55)",
  "border-radius:14px",
  "box-shadow:inset 0 1px 0 rgba(255,255,255,0.55)",
].join(";");

// ---- HTML ----
const html = `<!doctype html>
<html lang="hu">
<head>
  <meta name="color-scheme" content="light">
  <meta name="supported-color-schemes" content="light">
  <meta charset="utf-8">
  <meta name="x-apple-disable-message-reformatting">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Jó reggelt</title>
</head>
<body style="margin:0;padding:0;background:#f3f6fb;color:#111827;font-family:Arial,Helvetica,sans-serif;">
<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#f3f6fb;">

  <!-- preheader -->
  <div style="display:none;max-height:0;overflow:hidden;opacity:0;color:transparent;">
    Jó reggelt! Időjárás, ebéd, EUR/HUF és fűtési összegzés egy helyen.
  </div>

  <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#f3f6fb;">
    <tr>
      <td align="center" style="padding:18px 12px;">
        <table role="presentation" width="680" cellspacing="0" cellpadding="0" style="max-width:680px;width:100%;${GLASS_CARD}">

          <tr>
            <td style="padding:16px 16px 10px 16px;">
              <div style="font-size:22px;font-weight:700;line-height:1.2;">Jó reggelt! ☀️</div>
              <div style="margin-top:8px;font-size:14px;line-height:1.5;">
                Ma <b>${huDateLong}</b> van, <b>${namedayMain}</b> napja.
                ${namedayOtherShort ? `<span style="color:#6b7280;"> (további: ${namedayOtherShort})</span>` : ``}
              </div>
              <div style="margin-top:10px;font-size:14px;line-height:1.5;">
                Remélem, jól indult a reggel. Hoztam a gyors napi összefoglalót, hogy egy pillantással meglegyen minden fontos. 🙂
              </div>
              <div style="margin-top:10px;font-size:13px;line-height:1.5;color:#6b7280;">
                ${ICON.tip} ${tip}
              </div>


              <div style="margin-top:12px;font-size:14px;line-height:1.6;">
                ${ICON.weather} <b>Időjárás:</b> <b>${f.minTemp ?? '-'}–${f.maxTemp ?? '-'} °C</b>, ${f.trend ?? '-'}<br>
                ${ICON.rain} <b>Csapadék:</b> ${f.precipText ?? '-'}<br>
                ${ICON.wind} <b>Szél:</b> <b>${f.avgWind ?? '-'} km/h</b><br>
                ${ICON.sunrise} <b>Napkelte:</b> <b>${sunrise}</b> &nbsp;&nbsp; ${ICON.sunset} <b>Napnyugta:</b> <b>${sunset}</b>

              </div>

              ${kukaBlock}

              <div style="margin-top:12px;font-size:14px;line-height:1.6;">
                🍽 <b>Mai ebéd:</b> ${lunchText}<br>
                💶 <b>EUR/HUF:</b> 1 EUR = <b>${fx.rate ?? '-'}</b> HUF <span style="color:#6b7280;">(${fx.date ?? isoDate})</span>
              </div>
            </td>
          </tr>
        </table>

        <table role="presentation" width="680" cellspacing="0" cellpadding="0" style="max-width:680px;width:100%;${GLASS_CARD}">
          <tr>
            <td style="padding:14px 16px;">
              <div style="font-size:14px;font-weight:700;color:#2f6fb3;">📈 Elmúlt 24 óra összegzés</div>

              <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="margin-top:10px;">
                <tr>
                  <td style="padding:10px 12px;${GLASS_INNER}">
                    <div style="font-size:12px;color:#6b7280;">Kültéri átlag</div>
                    <div style="font-size:18px;font-weight:800;">${outAvgT} °C</div>
                  </td>
                  <td width="10"></td>
                  <td style="padding:10px 12px;${GLASS_INNER}">
                    <div style="font-size:12px;color:#6b7280;">Páratartalom</div>
                    <div style="font-size:18px;font-weight:800;">${outAvgH} %</div>
                  </td>
                  <td width="10"></td>
                  <td style="padding:10px 12px;${GLASS_INNER}">
                    <div style="font-size:12px;color:#6b7280;">Kazán működési idő</div>
                    <div style="font-size:18px;font-weight:800;color:#0f766e;">${boilerOnHHMM}</div>
                  </td>
                </tr>
              </table>

              <div style="margin-top:8px;font-size:12px;color:#6b7280;">
                5 perces mintavételezés, nagy adatkimaradásnál clampelve.
              </div>

              <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="margin-top:10px;border-collapse:collapse;">
                <tr>
