const toList = (v) => {
  if (Array.isArray(v)) return v.map(s => String(s).trim()).filter(Boolean);
  if (v == null) return [];
  return String(v).split(',').map(s => s.trim()).filter(Boolean);
};

// ha string jön, próbáljuk JSON-ként parse-olni
let o = msg.payload;
if (typeof o === 'string') {
  try { o = JSON.parse(o); } catch (e) { o = {}; }
}
if (!o || typeof o !== 'object') o = {};

const main = toList(o.nev1);
const other = toList(o.nev2);

msg.topic = 'nameday';
msg.payload = {
  main: main.join(', ') || '-',
  other: other.join(', '),
};

return msg;

const TZ = 'Europe/Budapest';

