// ════════════════════════════════════════════════════════════
//  == FUNCTION NODE: live_snapshot_writer ==
//  Elhelyezés: Unifier output után → mysql node
//
//  Mit csinál:
//  1. Az Unifier teljes outputját JSON-ként beírja live_snapshot-ba
//  2. Minden írásnál törli a 25 óránál régebbi sorokat
//
//  Kimenet 1 → mysql node (INSERT)
//  Kimenet 2 → mysql node (DELETE cleanup)
// ════════════════════════════════════════════════════════════

if (!msg.payload || !msg.payload._ts) return null;

const snapshot = {
    weather: msg.payload.weather || null,
    ac:      msg.payload.ac      || null,
    sensors: msg.payload.sensors || {},
    lights:  msg.payload.lights  || {}
};

// ── 1. kimenet: INSERT ───────────────────────────────────────
const insertMsg = {
    topic: "INSERT INTO live_snapshot (ts, payload) VALUES (NOW(3), ?)",
    payload: [ JSON.stringify(snapshot) ]
};

// ── 2. kimenet: DELETE régi sorok ───────────────────────────
// Minden 10. üzenetnél fut a cleanup (nem kell minden írásnál)
let writeCount = context.get("writeCount") || 0;
writeCount++;
context.set("writeCount", writeCount);

let cleanupMsg = null;
if (writeCount % 10 === 0) {
    cleanupMsg = {
        topic: "DELETE FROM live_snapshot WHERE ts < NOW() - INTERVAL 25 HOUR",
        payload: []
    };
}

// Node státusz
node.status({
    fill:  "green",
    shape: "dot",
    text:  `✓ ${new Date().toLocaleTimeString("hu-HU")}  |  #${writeCount}`
});

return [insertMsg, cleanupMsg];
